export const BODY: string = "\n<p>سیچوریشن اور وائبرینس دونوں رنگوں کو توانا کرتے ہیں، مگر الگ طریقوں سے۔ سیچوریشن سب رنگوں کو برابر بڑھاتی ہے، وائبرینس صرف مدھم رنگوں کو بڑھاتی ہے اور جلد کو بچاتی ہے۔</p>\n<p>فرق نہ جاننے سے پورٹریٹ نارنجی ہو جاتا ہے، کیونکہ سیچوریشن جلد کو بھی رنگ دیتی ہے۔ وائبرینس جلد کو چھوڑ کر باقی رنگ بڑھاتی ہے، اس لیے پورٹریٹ میں وہ بہتر ہے۔</p>\n<p>یہ مضمون دونوں کا موازنہ کرتا ہے، اور پورٹریٹ، منظر، مصنوعات اور سفر کے لیے درست انتخاب بتاتا ہے۔ ایڈٹ کرنے کے لیے <a href=\"/ur/tasveer-ki-saturation-badlein/\">امیج سیچوریشن ایڈیٹر</a> استعمال کریں۔</p>\n<h2 id=\"what-each-does\">ہر کنٹرول کیا کرتا ہے</h2>\n<p>سیچوریشن ہر رنگ کی شدت کو ایک جیسا بڑھاتی ہے: سرخ، نیلا اور سبز، سب برابر توانا ہوتے ہیں۔ وائبرینس صرف وہ رنگ بڑھاتی ہے جو مدھم ہیں، اور جو رنگ پہلے ہی توانا ہیں انہیں چھوڑ دیتی ہے۔</p>\n<p>سیچوریشن سیدھا اور طاقتور ہے، وائبرینس ہوشیار اور نرم ہے۔ دونوں کا مقصد رنگ توانا کرنا ہے، مگر طریقہ الگ ہے۔</p>\n<p>کنٹرول چنتے وقت تصویر دیکھیں: اگر سب رنگ مدھم ہوں تو سیچوریشن، اگر صرف کچھ رنگ مدھم ہوں تو وائبرینس۔</p>\n<h2 id=\"how-saturation-works\">سیچوریشن کیسے کام کرتی ہے</h2>\n<p>سیچوریشن ہر پکسل کے رنگ کی خالصیت بڑھاتی ہے۔ صفر پر تصویر سیاہ سفید ہو جاتی ہے، سو فیصد پر رنگ اپنی انتہا پر پہنچ جاتے ہیں۔</p>\n<p>سیچوریشن جلد کو بھی رنگ دیتی ہے، اس لیے پورٹریٹ میں وہ خطرناک ہے۔ تھوڑا سا اضافہ بھی جلد کو نارنجی کر دیتا ہے۔</p>\n<p>سیچوریشن منظر اور کھانے میں اچھی ہے، جہاں جلد نہیں ہوتی۔ وہاں وہ رنگوں کو توانا کرتی ہے، بغیر کسی نقصان کے۔</p>\n<h2 id=\"how-vibrance-works\">وائبرینس کیسے کام کرتی ہے</h2>\n<p>وائبرینس صرف مدھم رنگوں کو بڑھاتی ہے اور توانا رنگوں کو چھوڑ دیتی ہے۔ جلد کے رنگ کو وہ کم متاثر کرتی ہے، کیونکہ جلد کا رنگ پہلے ہی درمیانہ ہوتا ہے۔</p>\n<p>وائبرینس ہوشیار ہے: وہ تصویر کا توازن برقرار رکھتی ہے، جبکہ سیچوریشن توازن بگاڑ سکتی ہے۔ اسی لیے وائبرینس کو محفوظ انتخاب کہا جاتا ہے۔</p>\n<p>وائبرینس پورٹریٹ اور گروپ تصویروں میں بہترین ہے، جہاں جلد اہم ہے۔ وہ رنگ توانا کرتی ہے، بغیر جلد کو نارنجی کیے۔</p>\n<h2 id=\"key-differences\">اہم فرق، ساتھ ساتھ</h2>\n<p>سیچوریشن سب رنگ برابر بڑھاتی ہے، وائبرینس صرف مدھم رنگ بڑھاتی ہے۔ سیچوریشن جلد کو متاثر کرتی ہے، وائبرینس جلد کو بچاتی ہے۔</p>\n<p>سیچوریشن زیادہ طاقتور ہے، وائبرینس زیادہ نرم ہے۔ سیچوریشن سے رنگ غیر فطری ہو سکتے ہیں، وائبرینس سے کم ہوتے ہیں۔</p>\n<p>فرق جاننے کے لیے ایک ہی تصویر پر دونوں آزمائیں۔ جلد دیکھیں: جس میں جلد قدرتی لگے، وہی درست ہے۔</p>\n<h2 id=\"skin-tones\">جلد کے رنگ: جہاں وائبرینس جیتتی ہے</h2>\n<p>جلد کے رنگ میں وائبرینس واضح جیتتی ہے، کیونکہ وہ جلد کو کم متاثر کرتی ہے۔ پورٹریٹ میں وائبرینس سے رنگ توانا ہوتے ہیں، مگر جلد قدرتی رہتی ہے۔</p>\n<p>سیچوریشن پورٹریٹ میں جلد کو نارنجی کر دیتی ہے، خاص طور پر جب اضافہ زیادہ ہو۔ پورٹریٹ میں سیچوریشن سے بچیں۔</p>\n<p>پورٹریٹ میں پہلے وائبرینس آزمائیں۔ اگر وہ کافی نہ ہو تو سیچوریشن کو بہت ہلکا رکھیں۔</p>\n<h2 id=\"landscapes\">مناظر: دونوں کنٹرول کام کرتے ہیں</h2>\n<p>مناظر میں دونوں کام کرتے ہیں، کیونکہ وہاں جلد نہیں ہوتی۔ سیچوریشن آسمان اور ہریالی کو توانا کرتی ہے، وائبرینس بھی وہی کرتی ہے۔</p>\n<p>منظر میں سیچوریشن تھوڑی زیادہ بھی چل جاتی ہے، کیونکہ منظر میں جلد کا خطرہ نہیں۔ لیکن زیادہ سیچوریشن منظر کو کارٹون بنا دیتی ہے۔</p>\n<p>منظر میں پہلے وائبرینس آزمائیں، پھر ضرورت ہو تو سیچوریشن ہلکی رکھیں۔ دونوں مل کر بہترین نتیجہ دیتے ہیں۔</p>\n<h2 id=\"when-to-use-saturation\">سیچوریشن کب استعمال کریں</h2>\n<p>سیچوریشن اس وقت استعمال کریں جب سب رنگ مدھم ہوں اور جلد نہ ہو، جیسے منظر، کھانا یا مصنوعات۔ وہاں سیچوریشن تیز اور کارآمد ہے۔</p>\n<p>سیچوریشن اس وقت بھی استعمال کریں جب رنگ کو مکمل ہٹانا ہو: صفر پر تصویر سیاہ سفید ہو جاتی ہے۔</p>\n<p>سیچوریشن کو ہلکا رکھیں، دس سے بیس فیصد اضافہ اکثر کافی ہوتا ہے۔ زیادہ اضافہ رنگوں کو غیر فطری کر دیتا ہے۔</p>\n<h2 id=\"when-to-use-vibrance\">وائبرینس کب استعمال کریں</h2>\n<p>وائبرینس اس وقت استعمال کریں جب تصویر میں جلد ہو، جیسے پورٹریٹ، گروپ یا شادی۔ وہ رنگ توانا کرتی ہے، بغیر جلد کو خراب کیے۔</p>\n<p>وائبرینس اس وقت بھی استعمال کریں جب صرف کچھ رنگ مدھم ہوں۔ وہ صرف انہی کو بڑھاتی ہے، باقی کو چھوڑ دیتی ہے۔</p>\n<p>وائبرینس محفوظ انتخاب ہے: اگر شک ہو تو وائبرینس چنیں، سیچوریشن نہیں۔</p>\n<h2 id=\"combining-both\">دونوں کو ملانا</h2>\n<p>دونوں کو ملایا جا سکتا ہے: پہلے وائبرینس بڑھائیں، پھر سیچوریشن کو ہلکا رکھیں۔ اس سے رنگ توانا ہوتے ہیں اور جلد بھی محفوظ رہتی ہے۔</p>\n<p>ملاتے وقت دونوں کو ہلکا رکھیں۔ دونوں کو زیادہ رکھنے سے رنگ غیر فطری ہو جاتے ہیں۔</p>\n<p>دونوں کا مجموعہ بہترین نتیجہ دیتا ہے، اگر دونوں ہلکے ہوں۔ ایک کو زیادہ اور دوسرے کو کم رکھیں۔</p>\n<h2 id=\"over-saturation-signs\">حد سے زیادہ جانے کی نشانیاں</h2>\n<p>حد سے زیادہ کی نشانی یہ ہے کہ ایک رنگ دوسروں پر حاوی ہو جائے۔ گھاس نیون سبز، جلد نارنجی اور آسمان گہرا نیلا ہو جائے تو سمجھیں کہ حد سے زیادہ ہو گیا ہے۔</p>\n<p>دوسری نشانی یہ ہے کہ تصویر کارٹون جیسی لگنے لگے۔ قدرتی تصویر میں رنگ نرم ہوتے ہیں، کارٹون میں چیختے ہیں۔</p>\n<p>نشانی نظر آتے ہی سلائیڈر واپس کھسکائیں۔ قدرتی رنگ ہمیشہ بہتر لگتے ہیں۔</p>\n<h2 id=\"natural-colour-editing\">قدرتی رنگ کی ایڈیٹنگ: ایک فلسفہ</h2>\n<p>قدرتی رنگ کی ایڈیٹنگ کا مطلب ہے کہ تصویر اصلی جیسی لگے، مگر بہتر۔ رنگ توانا ہوں، مگر غیر فطری نہ ہوں۔</p>\n<p>قدرتی ایڈیٹنگ میں ہلکی تبدیلی کافی ہے۔ دس فیصد اضافہ اکثر کافی ہوتا ہے، پچاس فیصد کبھی نہیں۔</p>\n<p>قدرتی ایڈیٹنگ کا اصول یہ ہے کہ دیکھنے والا سوچے کہ تصویر ایسی ہی تھی، ایڈٹ نہیں کی گئی۔</p>\n<h2 id=\"muted-looks\">مدھم انداز: جب کم رنگ زیادہ ہو</h2>\n<p>مدھم انداز میں رنگ ہلکے ہوتے ہیں، مگر مکمل ختم نہیں ہوتے۔ یہ فیشن اور شادی کی تصویروں میں اچھا لگتا ہے۔</p>\n<p>مدھم کرنے کے لیے سیچوریشن کو بیس سے چالیس فیصد کم کریں۔ اگر تصویر بہت بھوری لگنے لگے تو تھوڑا رنگ واپس لائیں۔</p>\n<p>مدھم انداز نرم اور خوبصورت ہے، مگر ہر تصویر پر نہیں چلتا۔ منظر میں مدھم انداز بے جان لگتا ہے۔</p>\n<h2 id=\"black-and-white\">سیاہ سفید: رنگ ہٹانے کی انتہا</h2>\n<p>سیاہ سفید رنگ ہٹانے کی انتہا ہے: سیچوریشن صفر پر تصویر مکمل سیاہ سفید ہو جاتی ہے۔ یہ ڈرامائی اور دستاویزی احساس دیتا ہے۔</p>\n<p>سیاہ سفید میں تضاد اہم ہو جاتا ہے، کیونکہ رنگ نہیں رہتے۔ تضاد بڑھائیں، تاکہ تصویر میں گہرائی آئے۔</p>\n<p>سیاہ سفید ہر تصویر پر نہیں چلتا: رنگین منظر سیاہ سفید میں بے جان لگتا ہے، مگر پورٹریٹ میں وہ ڈرامائی لگتا ہے۔</p>\n<h2 id=\"product-photos\">مصنوعات کی تصویریں: چمک سے زیادہ درستگی</h2>\n<p>مصنوعات کی تصویر میں رنگ درست ہونا چاہیے، کیونکہ خریدار اسی رنگ کی توقع کرتا ہے۔ زیادہ سیچوریشن یا وائبرینس مصنوعات کا رنگ بدل دیتی ہے۔</p>\n<p>مصنوعات کے لیے دونوں کو کم رکھیں، یا بالکل نہ بڑھائیں۔ درستگی خوبصورتی سے زیادہ اہم ہے۔</p>\n<p>مصنوعات کی تصویر کو اصل رنگ سے ملا کر دیکھیں۔ اگر رنگ ملتے ہوں تو ایڈیٹنگ درست ہے۔</p>\n<h2 id=\"common-mistakes\">رنگ کنٹرول کے ساتھ عام غلطیاں</h2>\n<p>سب سے عام غلطی سیچوریشن کو آخر تک کھسکانا ہے۔ دوسری غلطی پورٹریٹ میں سیچوریشن استعمال کرنا ہے، جس سے جلد نارنجی ہو جاتی ہے۔</p>\n<p>تیسری غلطی دونوں کنٹرول کو زیادہ رکھنا ہے۔ دونوں کو ہلکا رکھیں، ایک کو زیادہ نہیں۔</p>\n<p>غلطیوں سے بچنے کے لیے پہلے وائبرینس آزمائیں، پھر سیچوریشن ہلکی رکھیں، اور جلد کو زوم کر کے دیکھیں۔</p>\n<h2 id=\"cheat-sheet\">کنٹرول چننے کی فوری یاد دہانی</h2>\n<p>پورٹریٹ کے لیے وائبرینس، منظر کے لیے دونوں، کھانے کے لیے سیچوریشن، اور مصنوعات کے لیے دونوں کم۔ شک ہو تو وائبرینس چنیں۔</p>\n<p>یاد دہانی کو فون میں محفوظ رکھیں، تاکہ ہر تصویر پر نیا فیصلہ نہ کرنا پڑے۔</p>\n<p>فوری فیصلہ کرنے کے لیے جلد دیکھیں: اگر تصویر میں جلد ہے تو وائبرینس، ورنہ سیچوریشن۔</p>\n<h2 id=\"vibrance-travel-photos\">سفر کی تصویروں کے لیے وائبرینس اور سیچوریشن</h2>\n<p>سفر کی تصویروں میں دونوں کام کرتے ہیں: وائبرینس لوگوں والی تصویروں میں اور سیچوریشن منظر میں۔ سفر کے البم میں دونوں کو ملا کر استعمال کریں۔</p>\n<p>سفر میں شدت درمیانی رکھیں، تاکہ جگہ کا احساس اصلی رہے۔ زیادہ رنگ سفر کی تصویر کو کارٹون بنا دیتا ہے۔</p>\n<p>سفر کے البم میں ایک ہی سیٹنگ رکھیں، تاکہ البم یکساں لگے۔ سیچوریشن کی مکمل رہنمائی <a href=\"/ur/blog/tasveer-saturation-editor-rehnumai/\">سیچوریشن ایڈیٹر رہنما</a> میں اور عملی مراحل <a href=\"/ur/blog/tasveer-ki-saturation-kaise-badlein/\">تصویر کی سیچوریشن کیسے بدلیں</a> میں دیکھیں۔ فلٹر کے لیے <a href=\"/ur/tasveer-filters/\">امیج فلٹرز</a> استعمال کریں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"سیچوریشن اور وائبرینس میں کیا فرق ہے؟","answer":"سیچوریشن سب رنگوں کو برابر بڑھاتی ہے، جبکہ وائبرینس صرف مدھم رنگوں کو بڑھاتی ہے اور جلد کو بچاتی ہے۔ پورٹریٹ میں وائبرینس بہتر ہے، منظر میں دونوں کام کرتے ہیں۔"},{"question":"پورٹریٹ کے لیے سیچوریشن بہتر ہے یا وائبرینس؟","answer":"وائبرینس بہتر ہے، کیونکہ وہ جلد کو نارنجی نہیں کرتی۔ سیچوریشن پورٹریٹ میں جلد کو خراب کر دیتی ہے، اس لیے اس سے بچیں۔"},{"question":"کیا میں ایک ہی تصویر پر سیچوریشن اور وائبرینس دونوں استعمال کر سکتا ہوں؟","answer":"جی ہاں، پہلے وائبرینس بڑھائیں، پھر سیچوریشن کو ہلکا رکھیں۔ دونوں کو ہلکا رکھیں، ورنہ رنگ غیر فطری ہو جائیں گے۔"},{"question":"سیچوریشن بڑھانے کے بعد میرا منظر جعلی کیوں لگتا ہے؟","answer":"کیونکہ سیچوریشن بہت زیادہ ہے۔ گھاس نیون سبز اور آسمان گہرا نیلا ہو جاتا ہے۔ شدت کم کریں یا وائبرینس آزمائیں، جو نرم ہے۔"},{"question":"کیا وائبرینس میری تصویر کی روشنی بدلتی ہے؟","answer":"نہیں، وائبرینس صرف رنگ بدلتی ہے، روشنی نہیں۔ لیکن رنگ توانا ہونے سے تصویر روشن محسوس ہوتی ہے، حالانکہ اصل روشنی وہی رہتی ہے۔"},{"question":"مصنوعات کی تصویروں کے لیے سیچوریشن استعمال کروں یا وائبرینس؟","answer":"دونوں کو کم رکھیں یا بالکل نہ بڑھائیں۔ مصنوعات میں رنگ کی درستگی سب سے اہم ہے، کیونکہ خریدار اسی رنگ کی توقع کرتا ہے۔"}];
